import crypto from 'node:crypto';

const BASE = 'http://127.0.0.1:9000';

async function getPublicKey() {
  const res = await fetch(`${BASE}/api/crypto/public_key`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ timestamp: Date.now(), fingerprint: crypto.randomUUID() }),
  });
  return (await res.json()).public_key;
}
function encrypt(publicKey, obj) {
  return crypto.publicEncrypt({ key: publicKey, padding: crypto.constants.RSA_PKCS1_PADDING }, Buffer.from(JSON.stringify(obj), 'utf8')).toString('base64');
}
const pk = await getPublicKey();
const loginRes = await fetch(`${BASE}/api/login`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ encrypted_params: encrypt(pk, { name: 'admin', password: 'NginxUi@2026' }) }),
});
const token = JSON.parse(await loginRes.text()).token;
const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
const r = await fetch(`${BASE}/api/sites`, { method: 'GET', headers: H });
const t = await r.text();
console.log(r.status);
console.log(t.slice(0, 4000));

