# 靖江物管（靖江物业公共服务平台, Vue2）本地 nginx 部署 —— root 指向本项目 dist
# 代理对齐 vite.config.js devServer.proxy：
#   /prod-api  -> unlimited.g.h5.admin.web.v1.wuguan.jingjiang.taizhou.dev.zhi.com/prod-api
#   /zhi2-dev  -> unlimited.g.h5.admin.web.v1.wuguan.jingjiang.taizhou.dev.zhi.com/zhi2-dev
server {
    listen 8104;
    server_name localhost;
    root D:/repository/靖江物管-wt-bug6045/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host unlimited.g.h5.admin.web.v1.wuguan.jingjiang.taizhou.dev.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }

    location ^~ /prod-api/ {
        proxy_pass http://unlimited.g.h5.admin.web.v1.wuguan.jingjiang.taizhou.dev.zhi.com/prod-api/;
    }
    location ^~ /zhi2-dev/ {
        proxy_pass http://unlimited.g.h5.admin.web.v1.wuguan.jingjiang.taizhou.dev.zhi.com/zhi2-dev/;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}

